import{_ as l,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017-MAY-18 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAY-18 :: Ceph Performance Weekly","date":"2017-05-26T00:00:00.000Z","updated":"2017-05-26T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息传递","锁优化","CRC计算","异步化","调试","测试","代码审查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.md"};function s(n,e,a,p,_,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2017年5月18日</p><p><strong>参会人员</strong>： 多名开发人员，包括Dave、Mark、Laurens、Igor、Nick、Stage、Marlon、Peter等。</p><p><strong>会议主题</strong>： 讨论Ceph存储系统相关的开发进展、性能优化、bug修复以及后续行动计划。</p><p><strong>会议内容</strong>：</p><p><strong>一、关键进展</strong></p><ul><li><strong>BlueStore优化</strong>： <ul><li>探讨了异步消息传递对减少锁争用和优化BlueStore性能的好处，计划进行测试。</li><li>讨论了优化管理器和BlueStore，并计划进行测试。</li><li>讨论了BlueFS同步选项的bug修复，并计划合并。</li></ul></li><li><strong>其他优化</strong>： <ul><li>讨论了CRC计算优化，并计划进行测试。</li><li>讨论了避免内存复制的优化，并计划进行测试。</li><li>讨论了KB sink PR，并计划进行测试。</li><li>讨论了scale优化，并计划进行测试。</li><li>讨论了Katie finisher的性能改进，并计划进行进一步测试。</li></ul></li><li><strong>Katie finisher</strong>： <ul><li>讨论了异步消息传递锁争用问题。</li><li>讨论了BlueStore的随机写性能。</li></ul></li><li><strong>其他议题</strong>： <ul><li>讨论了deferred right的优化。</li><li>讨论了BlueStore的I/O性能。</li><li>讨论了RocksDB同步问题。</li><li>讨论了PowerPC平台的优化。</li></ul></li></ul><p><strong>二、决定事项</strong></p><ul><li>对BlueStore进行异步消息传递和锁优化测试。</li><li>对CRC计算优化进行测试。</li><li>对KB sink PR进行测试。</li><li>对Katie finisher进行进一步测试。</li><li>对deferred right进行优化。</li><li>对BlueStore的I/O性能进行优化。</li><li>对RocksDB同步问题进行修复。</li><li>对PowerPC平台的优化进行讨论。</li></ul><p><strong>三、后续行动计划</strong></p><ul><li>各开发人员将继续进行代码开发和测试。</li><li>定期召开会议，讨论开发进展和问题。</li><li>及时更新文档和代码库。</li></ul><p><strong>四、其他</strong></p><ul><li>会议中还讨论了一些其他议题，例如RBD的优化、OSD的优化等。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph存储系统开发的相关议题，并制定了后续的行动计划。开发人员将继续努力，优化Ceph的性能和功能，为用户提供更好的存储解决方案。</p>',15)])])}const d=l(o,[["render",s]]);export{c as __pageData,d as default};
